XMLIndexTOCStylesContext::XMLIndexTOCStylesContext(
    SvXMLImport& rImport, Reference<XPropertySet> & rPropSet)
    : SvXMLImportContext(rImport)
    , rTOCPropertySet(rPropSet)
    , nOutlineLevel(0)
